head.script:
let objParent = $p.parent();



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > P > validator]<br/>컴포넌트에서 포커스가 해제될때 입력값 검증을 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "displaymessage=true 일때 validate() 메소드에 의해 alert 창이 표시되면 사용자 정의 함수가 실행되고 포커스가 해제될때 한번 더 실행됩니다.",
        "displaymessage=true 일때 validateObject() 메소드에 의해 alert 창이 표시되면 사용자 정의 함수가 실행되고 포커스가 해제될때 한번 더 실행됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 재생성
scwin.comp_init = function () {
    // comp 생성 호출
    objParent.scwin.comp_init();
};



// 사용자 정의 함수
objParent.scwin.fn_validator = function(val, id) { 
    wf_body_bottom.getObj("scwin").setReturnValue("excute user define function")
}



scwin.btn_validate_onclick = function (e) {
    objParent.target1.validate();
};



scwin.btn_validateObject_onclick = function (e) {
    objParent.target1.validateObject();
};
